/**
 * Internal carrier tracking (FedEx-branded UI).
 * Numbers are generated by us for demo/ops until a real FedEx API is connected.
 * Store under Order.internalNotes JSON keys: carrierTracking, shipmentEvents.
 */

export type ShipmentEvent = {
  code: string;
  label: string;
  detail: string;
  at: string; // ISO
  location?: string;
};

export type ShippingMeta = {
  carrierTracking?: string;
  carrierTrackingIssuedAt?: string;
  shipmentEvents?: ShipmentEvent[];
  [key: string]: unknown;
};

/** 12-digit style number (looks like express tracking). Prefix 7946 = our internal series. */
export function generateTrackingNumber() {
  const body = Array.from({ length: 8 }, () => Math.floor(Math.random() * 10)).join('');
  return `7946${body}`;
}

export function parseOrderMeta(raw: string | null | undefined): ShippingMeta {
  if (!raw) return {};
  try {
    return JSON.parse(raw) as ShippingMeta;
  } catch {
    return {};
  }
}

export function stringifyOrderMeta(meta: ShippingMeta) {
  return JSON.stringify(meta);
}

/** Ensure a tracking number exists once payment is confirmed. */
export function ensureTrackingOnMeta(meta: ShippingMeta, now = new Date()): ShippingMeta {
  if (meta.carrierTracking) return meta;
  const issued = now.toISOString();
  const tracking = generateTrackingNumber();
  const events: ShipmentEvent[] = [
    {
      code: 'LABEL',
      label: 'Shipping label created',
      detail: 'Vehicle assigned to transport. Tracking number issued.',
      at: issued,
      location: 'New York, NY',
    },
  ];
  return {
    ...meta,
    carrierTracking: tracking,
    carrierTrackingIssuedAt: issued,
    shipmentEvents: events,
  };
}

/** Advance simulated movement based on order status (admin actions). */
export function syncShipmentEvents(
  meta: ShippingMeta,
  orderStatus: string,
  now = new Date()
): ShippingMeta {
  const withTrack = ensureTrackingOnMeta(meta, now);
  const events = [...(withTrack.shipmentEvents || [])];
  const has = (code: string) => events.some((e) => e.code === code);
  const iso = now.toISOString();

  if (orderStatus === 'PAID' || orderStatus === 'PROCESSING' || orderStatus === 'DELIVERED' || orderStatus === 'COLLECTED') {
    if (!has('PICKED_UP')) {
      events.push({
        code: 'PICKED_UP',
        label: 'Picked up',
        detail: 'Vehicle collected from origin facility for worldwide transport.',
        at: iso,
        location: 'Origin hub',
      });
    }
  }

  if (orderStatus === 'PROCESSING' || orderStatus === 'DELIVERED' || orderStatus === 'COLLECTED') {
    if (!has('IN_TRANSIT')) {
      events.push({
        code: 'IN_TRANSIT',
        label: 'In transit',
        detail: 'Shipment is moving through the carrier network toward the delivery address.',
        at: iso,
        location: 'In transit',
      });
    }
  }

  if (orderStatus === 'DELIVERED' || orderStatus === 'COLLECTED') {
    if (!has('OUT_FOR_DELIVERY')) {
      events.push({
        code: 'OUT_FOR_DELIVERY',
        label: 'Out for delivery',
        detail: 'Final mile: vehicle is out for delivery or collection handover.',
        at: iso,
        location: 'Destination area',
      });
    }
    if (!has('DELIVERED')) {
      events.push({
        code: 'DELIVERED',
        label: orderStatus === 'COLLECTED' ? 'Collected' : 'Delivered',
        detail: 'Shipment completed. Handover and paperwork finalized.',
        at: iso,
        location: 'Delivery address',
      });
    }
  }

  // Sort chronologically
  events.sort((a, b) => new Date(a.at).getTime() - new Date(b.at).getTime());

  return { ...withTrack, shipmentEvents: events };
}

export function currentShipmentStatus(events: ShipmentEvent[] | undefined) {
  if (!events || events.length === 0) return 'Label pending';
  return events[events.length - 1]?.label || 'In progress';
}
